import subprocess, struct, sys
def mk(prop,d,u,body=b''):
    return bytes([prop])+struct.pack('<I',d)+struct.pack('<Q',u)+body
def run(data,args):
    open('/tmp/probe-alone/x.bin','wb').write(data)
    p=subprocess.run(['/workspace/executable']+args+['-c','/tmp/probe-alone/x.bin'],capture_output=True)
    return p.returncode, p.stderr.decode().strip().replace('/workspace/executable: ','')
vals=[]
for n in range(0,33):
    v=1<<n
    if v<=0xFFFFFFFF: vals.append(v)
    v2=(1<<n)+(1<<(n-1)) if n>=1 else None
    if v2 and v2<=0xFFFFFFFF: vals.append(v2)
vals += [0,3,5,7,0xFFFFFFFF,0xFFFFFFFE,0xFFFFFFFD,0x7FFFFFFF,0xBFFFFFFF,0xC0000001]
vals=sorted(set(vals))
for v in vals:
    rc,err=run(mk(0x5d,v,0xFFFFFFFFFFFFFFFF),['-d'])
    rc2,err2=run(mk(0x5d,v,0xFFFFFFFFFFFFFFFF),['-d','--format=lzma'])
    print("0x%08X %-10d auto:[%s] forced:[%s]"%(v,v,err,err2))
EOF
